<script setup lang="ts">
import { nextTick, onUnmounted, ref } from 'vue';
import { ElMessageBox } from 'element-plus';
import type { components } from '@ism/api-client';
import { useSessionStore } from '../stores/session';
const props=defineProps<{applicationId:string;publication:components['schemas']['AdmissionPublicResult'];canAdjust:boolean}>();const emit=defineEmits<{changed:[]}>();const client=useSessionStore().client;
const busy=ref(false),error=ref(''),notice=ref(''),mode=ref<'CORRECT'|'WITHDRAW'>(),comment=ref(''),reason=ref(''),formVersion=ref(0),panel=ref<HTMLElement>(),errorPanel=ref<HTMLElement>();
const pending=ref<{kind:'CORRECT'|'WITHDRAW';version:number;reason:string;publicComment:string}>(),history=ref<components['schemas']['AdmissionResultHistoryResponse']['data']>();const abort=new AbortController();let disposed=false;
async function fail(message:string){if(disposed)return;error.value=message;await nextTick();errorPanel.value?.focus();}
async function begin(kind:'CORRECT'|'WITHDRAW'){if(busy.value||pending.value)return;mode.value=kind;formVersion.value=props.publication.publicationVersion;comment.value=props.publication.publicComment;reason.value='';error.value='';notice.value='';await nextTick();panel.value?.focus();}
function cancel(){if(busy.value||pending.value)return;mode.value=undefined;comment.value='';reason.value='';}
async function load(page=0){if(busy.value||disposed)return;busy.value=true;error.value='';try{const result=await client.GET('/admissions/{id}/public-results/{publicationId}/history',{params:{path:{id:props.applicationId,publicationId:props.publication.id},query:{page,size:10}},signal:abort.signal});if(disposed)return;if(!result.data)throw new Error(result.error?.error.message??'历史读取失败');history.value=result.data.data;}catch(e){await fail(e instanceof Error?e.message:'历史读取失败');}finally{if(!disposed)busy.value=false;}}
async function submit(){if(busy.value||!mode.value||disposed)return;if(!pending.value){if(!reason.value.trim()||mode.value==='CORRECT'&&!comment.value.trim())return fail('请填写供应商可见原因及更正后的说明。');const draft={kind:mode.value,version:formVersion.value,reason:reason.value.trim(),publicComment:mode.value==='CORRECT'?comment.value.trim():''};try{await ElMessageBox.confirm(draft.kind==='CORRECT'?'新说明和更正原因将对供应商公开；原文本保留在员工历史中，准入决定不变。确认追加更正？':'撤销后门户仅保留撤销提示，不再提供旧说明；此发布不可恢复，原准入决定不变。确认撤销发布？',draft.kind==='CORRECT'?'追加更正准入说明':'撤销准入结果发布',{type:'warning'});}catch{return;}if(disposed)return;pending.value=draft;}busy.value=true;error.value='';let done=false;try{const command=pending.value;const result=command.kind==='CORRECT'?await client.POST('/admissions/{id}/public-results/{publicationId}/correct',{params:{path:{id:props.applicationId,publicationId:props.publication.id}},body:{version:command.version,reason:command.reason,publicComment:command.publicComment},signal:abort.signal}):await client.POST('/admissions/{id}/public-results/{publicationId}/withdraw',{params:{path:{id:props.applicationId,publicationId:props.publication.id}},body:{version:command.version,reason:command.reason},signal:abort.signal});if(disposed)return;if(!result.data){if([400,403,404,409,422].includes(result.response.status))pending.value=undefined;throw new Error(result.error?.error.message??'调整结果未确认');}notice.value=result.data.data.publicationState==='WITHDRAWN'?'当前记录已撤销发布，原准入决定不变。':`当前公开说明已更新（第 ${result.data.data.publicationVersion} 次调整），原准入决定不变。`;pending.value=undefined;mode.value=undefined;reason.value='';comment.value='';done=true;emit('changed');}catch(e){await fail((e instanceof Error?e.message:'网络异常')+(pending.value?'；结果未知，原请求已锁定，可刷新结果核查或重试同一调整。':'；请刷新结果后核查。'));}finally{if(!disposed)busy.value=false;}if(done&&history.value&&!disposed)await load(history.value.page);}
onUnmounted(()=>{disposed=true;abort.abort();pending.value=undefined;});
</script>
<template><div class="result-actions" :aria-busy="busy"><div v-if="error" ref="errorPanel" role="alert" tabindex="-1"><el-alert :title="error" type="error" :closable="false"/></div><p v-if="notice" role="status">{{notice}}</p><div class="buttons"><el-button :disabled="busy" @click="load(history?.page??0)">查看发布更正记录</el-button><template v-if="canAdjust&&publication.publicationState==='ACTIVE'"><el-button :disabled="busy||!!pending" @click="begin('CORRECT')">更正公开说明</el-button><el-button :disabled="busy||!!pending" type="warning" plain @click="begin('WITHDRAW')">撤销此结果发布</el-button></template></div>
 <div v-if="mode" ref="panel" tabindex="-1"><el-form label-position="top" @submit.prevent="submit"><p>调整针对发布记录 {{publication.id}}，基于发布版本 {{formVersion}}，不修改原准入决定。</p><el-form-item v-if="mode==='CORRECT'" label="更正后的供应商可见说明"><el-input v-model="comment" type="textarea" maxlength="1000" :rows="4" :disabled="busy||!!pending"/></el-form-item><el-form-item :label="mode==='CORRECT'?'供应商可见更正原因':'供应商可见撤销原因'"><el-input v-model="reason" type="textarea" maxlength="500" :rows="3" :disabled="busy||!!pending"/></el-form-item><el-button type="primary" :disabled="busy" @click="submit">{{pending?'重试同一发布调整':mode==='CORRECT'?'确认追加说明更正':'确认撤销对外发布'}}</el-button><el-button :disabled="busy||!!pending" @click="cancel">取消本次调整</el-button></el-form></div>
 <div v-if="history" class="change-history"><p class="text">原始公开说明（员工历史）：{{history.originalComment}}</p><div v-for="entry in history.items" :key="entry.version"><h5>第 {{entry.version}} 次调整 · {{entry.kind==='CORRECT'?'更正说明':'撤销发布'}}</h5><p>调整时间（北京时间）：{{new Date(entry.changedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}}</p><p v-if="entry.publicComment" class="text">当次更正说明：{{entry.publicComment}}</p><p class="text">当次原因：{{entry.reason}}</p></div><p v-if="!history.items.length">尚无更正或撤销记录。</p><div class="buttons"><el-button :disabled="busy||history.page===0" @click="load(history.page-1)">上一页发布调整</el-button><span>第 {{history.page+1}} 页，共 {{history.total}} 条</span><el-button :disabled="busy||(history.page+1)*history.size>=history.total" @click="load(history.page+1)">下一页发布调整</el-button></div></div>
</div></template>
<style scoped>.result-actions{margin:12px 0;min-width:0;overflow-wrap:anywhere}.buttons{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.buttons :deep(.el-button+.el-button){margin-left:0}.text{white-space:pre-wrap;overflow-wrap:anywhere}.change-history{margin-top:16px;border-top:1px solid var(--el-border-color)}</style>
